    /** Lowercase, drop a trailing parenthetical like " (Qulipta)", collapse separators. */
    private fun normKey(s: String?): String =
        (s ?: "").substringBefore('(').trim().lowercase()
            .replace(Regex("[ /-]+"), "_").trim('_')

    private val HIGH_LOW = Regex("_(high|low)${'$'}")

    /**
     * The order to walk when the caller cannot name a kind. Shared via
     * manifest.json so Android, iOS and the two RN apps cannot drift apart.
     */
    val KIND_ORDER: List<String> = listOf(
        "medicine",
        "trigger",
        "prodrome",
        "symptom",
        "relief",
        "missed",
        "activity",
        "location",
        "painCharacter",
    )

    /**
     * Art key for a pool item, or null when nothing in the set fits.
     *
     * `kind = null` is the Insights case: a correlation factor name belongs to no
     * single pool, so every kind is tried in KIND_ORDER. Note the global rules run
     * ONCE, after every kind's own rules — calling this per-kind in a loop instead
     * let the first kind fall through to the globals before a later kind's
     * specific rules ever ran, which is how "Fatigue" resolved through the
     * medicine pass and never reached the symptom key map.
     */
    fun keyFor(label: String?, iconKey: String?, category: String?, kind: String?): String? {
        val order = if (kind != null) listOf(kind) else KIND_ORDER
        val ik = normKey(iconKey)
        val lab = normKey(label)
        val candidates = listOf(
            ik, HIGH_LOW.replace(ik, ""), normKey(category),
            lab, HIGH_LOW.replace(lab, "")
        ).filter { it.isNotEmpty() }
        for (k in order) {
            val map = KIND_MAPS[k] ?: continue
            for (c in candidates) map[c]?.let { return it }
        }
        val plain = (label ?: "").substringBefore('(').trim().lowercase()
        if (plain.isNotEmpty()) {
            for (k in order) {
                for ((re, art) in KIND_RULES[k].orEmpty()) if (re.containsMatchIn(plain)) return art
            }
            for ((re, art) in GLOBAL_RULES) if (re.containsMatchIn(plain)) return art
        }
        return null
    }

    /** Brainy drawable for a pool item, or null so the caller keeps its glyph. */
    fun drawableFor(label: String?, iconKey: String?, category: String?, kind: String?): Int? =
        keyFor(label, iconKey, category, kind)?.let { ART[it] }
}
